package pzvrphysicality;

import java.lang.reflect.Field;import java.util.*;import local.pzvr.*;import viewpoint.core.Frame;import viewpoint.render.ModelDraws;import zombie.characters.*;import zombie.core.skinnedmodel.model.*;

/** Applies one small world translation to the current serialized wrist subtree, socket and rigid prop together. */
public final class HeldContactLimiter {
 private record Access(Field values,Field instances,Field palette,Field shadow,Field poses){}
 private static Access access;private static final ThreadLocal<Deque<Scope>> scopes=new ThreadLocal<>();private static final Scope INACTIVE=new Scope();
 private static final class Scope {final Frame frame;final IsoPlayer actor;final XrBackend.Frame input;final long epoch,time,receipt;final Thread owner;final int first,last;final ModelInstance[] instances;boolean valid;
  Scope(){frame=null;actor=null;input=null;epoch=time=receipt=-1;owner=null;first=last=0;instances=null;}
  Scope(Frame frame,IsoPlayer actor,int first,int last,ModelInstance[] instances){this.frame=frame;this.actor=actor;this.first=first;this.last=last;this.instances=instances;input=Engine.latestInput;epoch=HeldContactDriver.epoch();owner=Thread.currentThread();time=System.nanoTime();receipt=NativeRig.posedAt;valid=true;}}
 private static Access access()throws ReflectiveOperationException{if(access==null)access=new Access(field("values"),field("instances"),field("palette"),field("shadowPalette"),field("palettes"));return access;}private static Field field(String name)throws ReflectiveOperationException{var field=ModelDraws.class.getDeclaredField(name);field.setAccessible(true);return field;}
 public static void begin(Object raw,ModelSlotRenderData slot,IsoGameCharacter actor){var stack=scopes.get();if(!HeldContactDriver.enabled()&&stack==null)return;if(stack==null){stack=new ArrayDeque<>();scopes.set(stack);}Scope scope=INACTIVE;try{if(HeldContactDriver.enabled()&&HeldContactDriver.visualConstraints()&&raw instanceof Frame frame&&actor instanceof IsoPlayer p&&IsoPlayer.players.length>0&&p==IsoPlayer.players[0]&&slot!=null&&slot.character==actor&&Engine.latestInput!=null&&Engine.latestInput.focused()){int count=frame.scene.models.count(),size=slot.modelData.size(),first=count-size;if(size<1||size>128||first<0||count>4096)throw new IllegalArgumentException("Held actor record scope");var instances=(ModelInstance[])access().instances.get(frame.scene.models);if(count>instances.length)throw new IllegalArgumentException("Held actor packet");for(int n=0;n<size;n++)if(slot.modelData.get(n)==null||slot.modelData.get(n).modelInstance!=instances[first+n])throw new IllegalArgumentException("Held native actor record identity");scope=new Scope(frame,p,first,count,Arrays.copyOfRange(instances,first,count));}}catch(ReflectiveOperationException|RuntimeException|LinkageError unavailable){scope=INACTIVE;}stack.push(scope);}
 private static boolean current(Scope scope){if(scope==INACTIVE||!scope.valid||scope.owner!=Thread.currentThread()||scope.epoch!=HeldContactDriver.epoch()||!HeldContactDriver.enabled()||!HeldContactDriver.visualConstraints()||scope.input!=Engine.latestInput||!scope.input.focused()||IsoPlayer.players.length==0||scope.actor!=IsoPlayer.players[0]||scope.frame.scene.models.count()!=scope.last)return false;long now=System.nanoTime();return now>=scope.time&&now-scope.time<150_000_000L;}
 public static void end(Throwable failure){var stack=scopes.get();if(stack==null||stack.isEmpty())return;var scope=stack.pop();try{if(failure!=null||!current(scope)||NativeRig.posedAt==scope.receipt||NativeRig.posedAt<scope.time)return;apply(scope);}finally{scope.valid=false;if(stack.isEmpty())scopes.remove();}}
 private static void apply(Scope scope){try{var a=access();var draws=scope.frame.scene.models;var values=(float[])a.values.get(draws);var poses=(float[])a.poses.get(draws);var instances=(ModelInstance[])a.instances.get(draws);var palette=(int[])a.palette.get(draws);var shadow=(int[])a.shadow.get(draws);if(scope.last>values.length/68||scope.last>instances.length||scope.last>palette.length||scope.last>shadow.length||poses.length>262144)throw new IllegalArgumentException("Held current packet extent");for(int row=scope.first;row<scope.last;row++)if(instances[row]!=scope.instances[row-scope.first])return;
   HeldContactDriver.capture(scope.frame);var plan=new HeldContactPalette.Plan();boolean corrected=false;var selectedSamples=new ArrayList<HeldContactCapture.Sample>();for(var sample:HeldContactDriver.samples()){if(sample.actor()!=scope.actor||sample.scene()!=scope.frame.scene||sample.input()!=scope.input||!HeldContactCapture.current(sample,System.nanoTime()))continue;var response=HeldContactDriver.response(sample.side());if(response==null||response.distance()<.001*sample.units())continue;double[] render=HeldContactPalette.render(response.translation(),sample.units(),HeldContactDriver.maxCorrection());int item=-1;for(int row=scope.first;row<scope.last;row++)if(instances[row]==sample.instance()){if(item!=-1)throw new IllegalArgumentException("Ambiguous held prop");item=row;}if(item<0)continue;boolean wrist=false;for(int row=scope.first;row<scope.last;row++){var instance=instances[row];if(instance==null||instance.model==null||!(instance.model.tag instanceof SkinningData skin))continue;if(instance.model.mesh==null||!instance.model.mesh.isReady()||instance.model.mesh.skinningData!=skin||skin.skeletonHierarchy==null||skin.boneIndices==null||skin.skeletonHierarchy.size()>256)throw new IllegalArgumentException("Held bone layout unavailable");String name=sample.side()==0?"Bip01_L_Hand":"Bip01_R_Hand",prop=sample.side()==0?"Bip01_Prop2":"Bip01_Prop1";Integer root=skin.boneIndices.get(name),socket=skin.boneIndices.get(prop);if(root==null)throw new IllegalArgumentException("Held native wrist absent");boolean[] selected=HeldContactPalette.subtree(skin.skeletonHierarchy,root,socket==null?-1:socket);var placement=Arrays.copyOfRange(values,row*68,row*68+16);double[] local=HeldContactPalette.local(render,placement);HeldContactPalette.palette(plan,poses,palette[row],selected,local);if(shadow[row]>=0)HeldContactPalette.palette(plan,poses,shadow[row],selected,local);wrist=true;}if(!wrist)throw new IllegalArgumentException("No current serialized native wrist");HeldContactPalette.item(plan,values,item,render);selectedSamples.add(sample);corrected=true;}
   if(corrected&&current(scope)&&plan.commit(()->current(scope)&&selectedSamples.stream().allMatch(s->HeldContactCapture.current(s,System.nanoTime())))){HeldContactDriver.visualStatus("Bounded current hand and prop contact correction applied");}
  }catch(ReflectiveOperationException|RuntimeException|LinkageError unsupported){HeldContactDriver.visualStatus("Native pose retained: visual contact layout unavailable");}}
 private HeldContactLimiter(){}
}
